async function updateObject(ev,id){
  ev.preventDefault();const o=state.objects.find(item=>item.id===id);if(!o)return;
  const f=Object.fromEntries(new FormData(ev.target)),before={title:o.title,area:o.area,owner:o.owner,status:o.status,priority:o.priority,start:o.start,due:o.due,budget:o.budget,product:o.product,description:o.description},changes={title:f.title,area:f.area,owner:f.owner,status:f.status,priority:f.priority,start:f.start,due:f.due,budget:parseBrazilianCurrency(f.budget),product:f.product,description:f.description};
  if(backend&&o.dbId){try{const {doc,collection,writeBatch,serverTimestamp}=backend.dataSdk,batch=writeBatch(backend.db),objectRef=doc(backend.db,'objects',o.dbId),auditRef=doc(collection(backend.db,'audit')),eventRef=doc(collection(backend.db,'events'));batch.update(objectRef,{title:changes.title,area:changes.area,ownerName:changes.owner,status:changes.status,priority:changes.priority,plannedStart:changes.start,plannedEnd:changes.due,budget:changes.budget,product:changes.product,description:changes.description,updatedAt:serverTimestamp(),updatedBy:session.id});batch.set(eventRef,{objectId:o.dbId,objectCode:o.id,eventType:'Edição',description:'Dados principais do objeto atualizados',createdBy:session.id,createdByName:session.name,eventAt:serverTimestamp()});batch.set(auditRef,{userId:session.id,userName:session.name,action:'UPDATE',entity:'objects',recordId:o.dbId,oldData:before,newData:changes,createdAt:serverTimestamp()});await batch.commit()}catch(error){return toast('Erro ao atualizar objeto: '+error.message)}}
  Object.assign(o,changes);state.events.unshift({id:crypto.randomUUID(),objectId:o.id,date:new Date().toLocaleString('sv-SE').slice(0,16),type:'Edição',text:'Dados principais do objeto atualizados',user:session.name});save();closeModal();toast('Objeto atualizado com sucesso.');render()
}

